+:root{
+  color-scheme: dark;
+
+  /* Brand (OKLCH-first) */
+  --sw-red: oklch(58% 0.26 27);
+  --sw-red-2: oklch(52% 0.23 27);
+  --sw-bg: oklch(18% 0.01 270);
+  --sw-bg-2: oklch(21% 0.01 270);
+  --sw-surface: oklch(24% 0.01 270);
+  --sw-surface-2: oklch(28% 0.01 270);
+  --sw-border: oklch(35% 0.01 270);
+  --sw-text: oklch(96% 0.01 270);
+  --sw-text-2: oklch(80% 0.02 270);
+  --sw-muted: oklch(70% 0.02 270);
+
+  --shadow-lg: 0 24px 80px rgba(0,0,0,.55);
+  --shadow-md: 0 16px 44px rgba(0,0,0,.50);
+  --radius-lg: 18px;
+  --radius-md: 14px;
+  --radius-sm: 12px;
+
+  --space-1: 4px;
+  --space-2: 8px;
+  --space-3: 16px;
+  --space-4: 24px;
+  --space-5: 32px;
+  --space-6: 48px;
+  --space-7: 64px;
+  --space-8: 96px;
+
+  --container: 1200px;
+  --font-sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+  --font-display: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial;
+}
+
+*{box-sizing:border-box;}
+
+html,body{height:100%;}
+
+body{
+  margin:0;
+  background: radial-gradient(1200px 700px at 30% -10%, rgba(229,9,20,.24), transparent 60%),
+              radial-gradient(900px 600px at 90% 0%, rgba(229,9,20,.16), transparent 55%),
+              linear-gradient(180deg, color-mix(in oklch, var(--sw-bg) 84%, black) 0%, var(--sw-bg) 40%, color-mix(in oklch, var(--sw-bg) 80%, black) 100%);
+  color: var(--sw-text);
+  font-family: var(--font-sans);
+  letter-spacing: .1px;
+}
+
+a{color:inherit;}
+
+.container{
+  width: min(var(--container), calc(100% - 32px));
+  margin: 0 auto;
+}
+
+.skip-link{
+  position:absolute;
+  left:-999px;
+  top:auto;
+  width:1px;
+  height:1px;
+  overflow:hidden;
+}
+
+.skip-link:focus{
+  left: 16px;
+  top: 16px;
+  width:auto;
+  height:auto;
+  padding: 10px 12px;
+  background: var(--sw-surface);
+  border: 1px solid var(--sw-border);
+  border-radius: 12px;
+  z-index: 9999;
+}
+
+/* Header */
+.site-header{
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  backdrop-filter: blur(10px);
+  background: color-mix(in oklch, var(--sw-bg) 72%, transparent);
+  border-bottom: 1px solid color-mix(in oklch, var(--sw-border) 55%, transparent);
+}
+
+.nav{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  padding: 14px 0;
+  gap: var(--space-3);
+}
+
+.brand{
+  display:flex;
+  align-items:center;
+  gap: 10px;
+  text-decoration:none;
+}
+
+.brand-mark{
+  width: 26px;
+  height: 26px;
+  border-radius: 9px;
+  background: linear-gradient(180deg, var(--sw-red) 0%, var(--sw-red-2) 100%);
+  box-shadow: 0 14px 30px rgba(229,9,20,.18);
+  position: relative;
+  overflow:hidden;
+}
+
+.brand-mark::after{
+  content:"";
+  position:absolute;
+  inset:-30% -40%;
+  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,.45), transparent 48%);
+  transform: rotate(12deg);
+}
+
+.brand-name{
+  font-family: var(--font-display);
+  font-weight: 800;
+  letter-spacing: .6px;
+  font-size: 18px;
+}
+
+.nav-actions{
+  display:flex;
+  align-items:center;
+  gap: 10px;
+}
+
+.select{
+  appearance:none;
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  background: color-mix(in oklch, var(--sw-surface) 78%, transparent);
+  color: var(--sw-text);
+  border-radius: 12px;
+  padding: 10px 38px 10px 12px;
+  font-size: 14px;
+  line-height: 1;
+  background-image:
+    linear-gradient(45deg, transparent 50%, var(--sw-text) 50%),
+    linear-gradient(135deg, var(--sw-text) 50%, transparent 50%);
+  background-position:
+    calc(100% - 18px) 52%,
+    calc(100% - 12px) 52%;
+  background-size: 6px 6px, 6px 6px;
+  background-repeat: no-repeat;
+}
+
+.btn{
+  border: 1px solid transparent;
+  border-radius: 14px;
+  padding: 10px 14px;
+  font-weight: 700;
+  font-size: 14px;
+  text-decoration:none;
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap: 10px;
+  cursor:pointer;
+  transition: transform .12s ease, filter .12s ease, background-color .12s ease, border-color .12s ease;
+}
+
+.btn:active{transform: translateY(1px);}
+
+.btn-primary{
+  background: linear-gradient(180deg, var(--sw-red) 0%, var(--sw-red-2) 100%);
+  color: white;
+  box-shadow: 0 18px 44px rgba(229,9,20,.20);
+}
+
+.btn-primary:hover{filter: brightness(1.05);} 
+
+.btn-ghost{
+  background: color-mix(in oklch, var(--sw-surface) 70%, transparent);
+  border-color: color-mix(in oklch, var(--sw-border) 70%, transparent);
+}
+
+.btn-ghost:hover{border-color: color-mix(in oklch, var(--sw-border) 92%, transparent);} 
+
+.btn-lg{
+  padding: 14px 16px;
+  font-size: 16px;
+  border-radius: 16px;
+}
+
+:focus-visible{
+  outline: 2px solid var(--sw-red);
+  outline-offset: 2px;
+}
+
+/* Hero */
+.hero{
+  position: relative;
+  padding: var(--space-7) 0 var(--space-6);
+}
+
+.hero::before{
+  content:"";
+  position:absolute;
+  inset: 0;
+  background:
+    radial-gradient(900px 600px at 20% 10%, rgba(229,9,20,.24), transparent 55%),
+    radial-gradient(900px 700px at 80% 10%, rgba(255,255,255,.06), transparent 60%),
+    linear-gradient(180deg, rgba(0,0,0,.70) 0%, rgba(0,0,0,.64) 30%, rgba(0,0,0,.85) 100%),
+    url("assets/posters.svg");
+  background-size: auto, auto, auto, cover;
+  background-position: center, center, center, center;
+  filter: saturate(1.05) brightness(.95);
+  border-bottom: 1px solid color-mix(in oklch, var(--sw-border) 55%, transparent);
+}
+
+.hero-inner{
+  position: relative;
+  padding: var(--space-7) 0;
+}
+
+.hero-grid{
+  display:grid;
+  gap: var(--space-5);
+}
+
+.hero h1{
+  margin:0;
+  font-family: var(--font-display);
+  font-weight: 900;
+  letter-spacing: .2px;
+  font-size: clamp(38px, 5vw, 64px);
+  line-height: 1.02;
+}
+
+.hero p{
+  margin: 12px 0 0;
+  color: var(--sw-text-2);
+  font-size: 16px;
+  line-height: 1.6;
+}
+
+.hero .price{
+  margin-top: 10px;
+  font-weight: 700;
+  color: color-mix(in oklch, var(--sw-text) 92%, var(--sw-text-2));
+}
+
+.email-cta{
+  margin-top: var(--space-4);
+  display:grid;
+  gap: 12px;
+}
+
+.email-cta .prompt{color: var(--sw-text-2);}
+
+.email-row{
+  display:grid;
+  grid-template-columns: 1fr;
+  gap: 10px;
+  max-width: 680px;
+}
+
+.field{
+  width:100%;
+  border-radius: 16px;
+  border: 1px solid color-mix(in oklch, var(--sw-border) 75%, transparent);
+  background: color-mix(in oklch, var(--sw-surface) 75%, transparent);
+  color: var(--sw-text);
+  padding: 14px 14px;
+  font-size: 16px;
+}
+
+.field::placeholder{color: color-mix(in oklch, var(--sw-text-2) 70%, transparent);} 
+
+.field:focus-visible{outline-color: var(--sw-red);}
+
+.assist{
+  color: color-mix(in oklch, var(--sw-text-2) 85%, transparent);
+  font-size: 13px;
+}
+
+/* Sections */
+section{padding: var(--space-7) 0;}
+
+.section-title{
+  margin:0 0 var(--space-4);
+  font-family: var(--font-display);
+  font-weight: 900;
+  letter-spacing: .3px;
+  font-size: clamp(24px, 3vw, 34px);
+}
+
+/* Trending carousel */
+.carousel-shell{
+  border-radius: var(--radius-lg);
+  background: linear-gradient(180deg, color-mix(in oklch, var(--sw-surface) 86%, transparent) 0%, color-mix(in oklch, var(--sw-surface) 76%, transparent) 100%);
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  padding: var(--space-4);
+  box-shadow: var(--shadow-md);
+}
+
+.carousel-head{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: var(--space-3);
+  margin-bottom: var(--space-3);
+}
+
+.carousel-actions{display:flex; gap: 10px;}
+
+.icon-btn{
+  width: 44px;
+  height: 44px;
+  border-radius: 14px;
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  background: color-mix(in oklch, var(--sw-surface) 70%, transparent);
+  color: var(--sw-text);
+  cursor:pointer;
+  transition: transform .12s ease, border-color .12s ease, filter .12s ease;
+}
+
+.icon-btn:hover{border-color: color-mix(in oklch, var(--sw-border) 92%, transparent);} 
+.icon-btn:active{transform: translateY(1px);} 
+
+.carousel{
+  display:flex;
+  gap: 14px;
+  overflow:auto;
+  scroll-snap-type: x mandatory;
+  padding-bottom: 6px;
+  -webkit-overflow-scrolling: touch;
+}
+
+.carousel::-webkit-scrollbar{height:10px;}
+.carousel::-webkit-scrollbar-thumb{background: color-mix(in oklch, var(--sw-border) 65%, transparent); border-radius: 999px;}
+.carousel::-webkit-scrollbar-track{background: transparent;}
+
+.poster{
+  position: relative;
+  flex: 0 0 240px;
+  height: 340px;
+  border-radius: 18px;
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  overflow:hidden;
+  background:
+    radial-gradient(140px 140px at 40% 25%, rgba(255,255,255,.15), transparent 60%),
+    linear-gradient(135deg, rgba(229,9,20,.22), rgba(255,255,255,.03));
+  box-shadow: 0 22px 64px rgba(0,0,0,.45);
+  scroll-snap-align: start;
+}
+
+.poster img{
+  width:100%;
+  height:100%;
+  object-fit: cover;
+  filter: brightness(.92) contrast(1.05);
+}
+
+.poster::after{
+  content:"";
+  position:absolute;
+  inset:0;
+  background: linear-gradient(180deg, rgba(0,0,0,.05) 0%, rgba(0,0,0,.65) 70%, rgba(0,0,0,.80) 100%);
+}
+
+.rank{
+  position:absolute;
+  left: 12px;
+  bottom: 6px;
+  font-family: var(--font-display);
+  font-weight: 950;
+  font-size: 110px;
+  line-height: .9;
+  color: rgba(255,255,255,.10);
+  text-shadow: 0 18px 60px rgba(0,0,0,.55);
+  z-index: 2;
+}
+
+.poster-title{
+  position:absolute;
+  left: 14px;
+  right: 14px;
+  bottom: 18px;
+  z-index: 3;
+  display:flex;
+  gap: 10px;
+  align-items:flex-end;
+}
+
+.poster-title .name{
+  font-weight: 850;
+  letter-spacing: .2px;
+  font-size: 16px;
+}
+
+.tag{
+  font-size: 12px;
+  color: color-mix(in oklch, var(--sw-text-2) 78%, transparent);
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  background: color-mix(in oklch, var(--sw-surface) 60%, transparent);
+  border-radius: 999px;
+  padding: 6px 10px;
+}
+
+/* Features */
+.features-grid{
+  display:grid;
+  gap: 14px;
+}
+
+.card{
+  border-radius: var(--radius-lg);
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  background: linear-gradient(180deg, color-mix(in oklch, var(--sw-surface) 88%, transparent) 0%, color-mix(in oklch, var(--sw-surface) 74%, transparent) 100%);
+  padding: 18px;
+  box-shadow: var(--shadow-md);
+  position: relative;
+  overflow:hidden;
+}
+
+.card h3{
+  margin:0;
+  font-family: var(--font-display);
+  letter-spacing: .2px;
+  font-weight: 900;
+  font-size: 18px;
+}
+
+.card p{
+  margin: 10px 0 0;
+  color: var(--sw-text-2);
+  line-height: 1.55;
+}
+
+.card .corner-icon{
+  position:absolute;
+  right: 14px;
+  bottom: 14px;
+  width: 46px;
+  height: 46px;
+  border-radius: 16px;
+  display:grid;
+  place-items:center;
+  background: color-mix(in oklch, var(--sw-surface-2) 70%, transparent);
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  color: color-mix(in oklch, var(--sw-red) 70%, white);
+}
+
+/* FAQ */
+.faq{
+  max-width: 900px;
+}
+
+.accordion{
+  display:grid;
+  gap: 10px;
+}
+
+.acc-item{
+  border-radius: var(--radius-lg);
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  overflow:hidden;
+  background: linear-gradient(180deg, color-mix(in oklch, var(--sw-surface) 88%, transparent) 0%, color-mix(in oklch, var(--sw-surface) 74%, transparent) 100%);
+}
+
+.acc-button{
+  width:100%;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 14px;
+  padding: 18px 18px;
+  background: transparent;
+  border: 0;
+  color: var(--sw-text);
+  cursor:pointer;
+  font-size: 16px;
+  font-weight: 800;
+  text-align:left;
+}
+
+.acc-button .plus{
+  width: 40px;
+  height: 40px;
+  border-radius: 14px;
+  display:grid;
+  place-items:center;
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  background: color-mix(in oklch, var(--sw-surface) 65%, transparent);
+  flex: 0 0 auto;
+}
+
+.acc-panel{
+  display:grid;
+  grid-template-rows: 0fr;
+  transition: grid-template-rows .28s ease;
+}
+
+.acc-panel > div{
+  overflow:hidden;
+  padding: 0 18px;
+  color: var(--sw-text-2);
+  line-height: 1.6;
+}
+
+.acc-item[data-open="true"] .acc-panel{grid-template-rows: 1fr;}
+.acc-item[data-open="true"] .acc-panel > div{padding-bottom: 18px;}
+
+.acc-item[data-open="true"] .acc-button .plus{border-color: color-mix(in oklch, var(--sw-red) 70%, transparent);} 
+
+/* CTA */
+.cta-block{
+  border-radius: 24px;
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  background:
+    radial-gradient(800px 400px at 15% 10%, rgba(229,9,20,.28), transparent 55%),
+    radial-gradient(700px 460px at 90% 10%, rgba(255,255,255,.08), transparent 55%),
+    linear-gradient(180deg, color-mix(in oklch, var(--sw-surface) 90%, transparent) 0%, color-mix(in oklch, var(--sw-surface-2) 82%, transparent) 100%);
+  padding: 22px;
+  box-shadow: var(--shadow-lg);
+}
+
+/* Footer */
+footer{
+  padding: var(--space-7) 0;
+  border-top: 1px solid color-mix(in oklch, var(--sw-border) 55%, transparent);
+  background: color-mix(in oklch, var(--sw-bg) 90%, black);
+}
+
+.footer-top{color: var(--sw-text-2); margin-bottom: var(--space-4);} 
+
+.footer-grid{
+  display:grid;
+  gap: 12px;
+}
+
+.footer-grid a{
+  color: color-mix(in oklch, var(--sw-text-2) 88%, transparent);
+  text-decoration:none;
+  font-size: 14px;
+}
+
+.footer-grid a:hover{text-decoration: underline;}
+
+.footer-bottom{
+  margin-top: var(--space-4);
+  display:flex;
+  flex-wrap: wrap;
+  gap: 12px;
+  align-items:center;
+  justify-content:space-between;
+  color: color-mix(in oklch, var(--sw-text-2) 86%, transparent);
+  font-size: 13px;
+}
+
+/* Login page */
+.auth-wrap{
+  min-height: calc(100vh - 72px);
+  display:grid;
+  place-items:center;
+  padding: var(--space-6) 0;
+}
+
+.auth-card{
+  width: min(480px, calc(100% - 32px));
+  border-radius: 24px;
+  border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+  background:
+    radial-gradient(600px 280px at 20% 0%, rgba(229,9,20,.22), transparent 55%),
+    linear-gradient(180deg, color-mix(in oklch, var(--sw-surface) 90%, transparent) 0%, color-mix(in oklch, var(--sw-surface-2) 82%, transparent) 100%);
+  box-shadow: var(--shadow-lg);
+  padding: 22px;
+}
+
+.auth-card h1{
+  margin:0;
+  font-family: var(--font-display);
+  font-weight: 950;
+  letter-spacing: .2px;
+  font-size: 28px;
+}
+
+.auth-card p{
+  margin: 10px 0 18px;
+  color: var(--sw-text-2);
+  line-height: 1.5;
+}
+
+.stack{display:grid; gap: 12px;}
+
+.help{
+  margin-top: 14px;
+  border-top: 1px solid color-mix(in oklch, var(--sw-border) 55%, transparent);
+  padding-top: 14px;
+}
+
+.help-toggle{
+  width:100%;
+  background: transparent;
+  border: 0;
+  color: var(--sw-text);
+  padding: 0;
+  font-weight: 800;
+  cursor:pointer;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+}
+
+.help-panel{
+  display:grid;
+  grid-template-rows: 0fr;
+  transition: grid-template-rows .26s ease;
+}
+
+.help-panel > div{overflow:hidden; color: var(--sw-text-2); padding-top: 0; line-height: 1.55;}
+
+.help[data-open="true"] .help-panel{grid-template-rows: 1fr;}
+.help[data-open="true"] .help-panel > div{padding-top: 10px;}
+
+.hint{font-size: 13px; color: color-mix(in oklch, var(--sw-text-2) 86%, transparent);} 
+
+/* Responsive */
+@media (min-width: 740px){
+  .email-row{grid-template-columns: 1fr auto;}
+  .btn-lg{padding: 14px 18px;}
+  .features-grid{grid-template-columns: repeat(2, minmax(0, 1fr));}
+  .footer-grid{grid-template-columns: repeat(4, minmax(0, 1fr));}
+}
+
+@media (min-width: 1024px){
+  .hero-grid{grid-template-columns: 1.1fr .9fr; align-items:center;}
+  .hero .hero-aside{
+    border-radius: 24px;
+    border: 1px solid color-mix(in oklch, var(--sw-border) 70%, transparent);
+    background: color-mix(in oklch, var(--sw-surface) 65%, transparent);
+    box-shadow: var(--shadow-md);
+    padding: 18px;
+  }
+  .features-grid{grid-template-columns: repeat(4, minmax(0, 1fr));}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto !important; transition:none !important;}
+}
+
*** End Patch
PATCH

